const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const arcDeTriomphe = ee.Geometry.Point([2.2950, 48.8738]);
  const versailles = ee.Geometry.Point([2.1204, 48.8049]);
  const date = '2024-08-06';
  const buffer = 500; // meters around each point

  const arcRegion = arcDeTriomphe.buffer(buffer);
  const versaillesRegion = versailles.buffer(buffer);

  // 2. Data Acquisition - Try MODIS Terra first, then Aqua
  let col = ee.ImageCollection('MODIS/061/MOD11A1')
    .filterDate(date, ee.Date(date).advance(1, 'day'))
    .filterBounds(arcDeTriomphe);

  let colSize = await col.size().getInfo();
  console.log(`MODIS Terra images found: ${colSize}`);

  if (colSize === 0) {
    // Try MODIS Aqua as fallback
    col = ee.ImageCollection('MODIS/061/MYD11A1')
      .filterDate(date, ee.Date(date).advance(1, 'day'))
      .filterBounds(arcDeTriomphe);
    colSize = await col.size().getInfo();
    console.log(`MODIS Aqua images found: ${colSize}`);
  }

  if (colSize === 0) {
    console.log('No MODIS LST data available for this date');
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Processing - Get daytime LST (in Kelvin * 0.02 scale factor)
  const img = col.first();
  const lstDay = img.select('LST_Day_1km');

  // Apply scale factor and convert to Celsius
  const lstCelsius = lstDay.multiply(0.02).subtract(273.15);

  // 4. Calculate mean LST for both locations
  const arcStats = await lstCelsius.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: arcRegion,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const versaillesStats = await lstCelsius.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: versaillesRegion,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const arcTemp = arcStats.LST_Day_1km_mean;
  const arcCount = arcStats.LST_Day_1km_count;
  const versaillesTemp = versaillesStats.LST_Day_1km_mean;
  const versaillesCount = versaillesStats.LST_Day_1km_count;

  console.log(`Arc de Triomphe: ${arcTemp?.toFixed(2)}C (pixels: ${arcCount})`);
  console.log(`Versailles: ${versaillesTemp?.toFixed(2)}C (pixels: ${versaillesCount})`);

  // 5. Validation & Final Answer
  if (arcCount === 0 || versaillesCount === 0) {
    console.log('No valid pixels after processing');
    console.log('<answer>C2</answer>');
    return;
  }

  if (arcTemp === null || versaillesTemp === null || 
      arcTemp === undefined || versaillesTemp === undefined ||
      isNaN(arcTemp) || isNaN(versaillesTemp) ||
      arcTemp < -50 || arcTemp > 60 || versaillesTemp < -50 || versaillesTemp > 60) {
    console.log('Invalid temperature values');
    console.log('<answer>C3</answer>');
    return;
  }

  const tempDiff = arcTemp - versaillesTemp;
  console.log(`Temperature difference: ${tempDiff.toFixed(2)}C`);

  if (tempDiff >= 5.0) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
